-- 003_helpers.sql — Notifications + Settings + Admin + Trigger
CREATE TABLE public.notifications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID REFERENCES public.user_profiles(id) ON DELETE CASCADE, title_ar TEXT, message_ar TEXT, type TEXT DEFAULT 'system', is_read BOOLEAN DEFAULT false, link_url TEXT, role_target TEXT DEFAULT 'all', created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE public.app_settings (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), key TEXT UNIQUE NOT NULL, value JSONB DEFAULT '{}'::jsonb, description TEXT, category TEXT DEFAULT 'general', updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE public.admin_actions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), admin_id UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL, action_type TEXT NOT NULL, target_table TEXT, target_id UUID, details JSONB DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ DEFAULT now());
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$ BEGIN INSERT INTO public.user_profiles (id, email, full_name, role) VALUES (NEW.id, NEW.email, COALESCE(NEW.raw_user_meta_data->>'full_name',''), COALESCE(NEW.raw_user_meta_data->>'role','retailer')::public.user_role) ON CONFLICT (id) DO NOTHING; RETURN NEW; END; $$;
